-- ============================================================
-- SoundByte — Script de Dados Sintéticos
-- Projeto Final Integrador · GBDBI · ESPM 2026
-- Execute em PostgreSQL: psql -d seu_banco -f soundbyte_projeto_final.sql
-- ============================================================

DROP TABLE IF EXISTS reproducao CASCADE;
DROP TABLE IF EXISTS assinatura CASCADE;
DROP TABLE IF EXISTS usuario CASCADE;
DROP TABLE IF EXISTS musica CASCADE;
DROP TABLE IF EXISTS album CASCADE;
DROP TABLE IF EXISTS artista CASCADE;
DROP TABLE IF EXISTS cidade CASCADE;
DROP TABLE IF EXISTS genero CASCADE;
DROP TABLE IF EXISTS plano CASCADE;

CREATE TABLE plano (
  id          SERIAL PRIMARY KEY,
  nome        VARCHAR(50) NOT NULL UNIQUE,
  preco_mensal NUMERIC(8,2) NOT NULL,
  max_devices  INT NOT NULL,
  recursos     TEXT
);

INSERT INTO plano (nome, preco_mensal, max_devices, recursos) VALUES
  ('gratuito',   0.00, 1, 'Anúncios, qualidade 128kbps, shuffle apenas'),
  ('estudante', 14.90, 1, 'Sem anúncios, qualidade 256kbps, download offline'),
  ('premium',   29.90, 3, 'Sem anúncios, qualidade 320kbps, download offline, acesso família'),
  ('familiar',  49.90, 6, 'Sem anúncios, qualidade 320kbps, 6 contas, controle parental');

CREATE TABLE genero (
  id   SERIAL PRIMARY KEY,
  nome VARCHAR(80) NOT NULL UNIQUE
);

INSERT INTO genero (nome) VALUES
