  ('R&B'),
  ('Indie');

CREATE TABLE cidade (
  id         SERIAL PRIMARY KEY,
  nome       VARCHAR(100) NOT NULL,
  estado     CHAR(2) NOT NULL,
  regiao     VARCHAR(20) NOT NULL,
  populacao_M NUMERIC(4,1)
);

