CREATE TABLE artista (
  id           SERIAL PRIMARY KEY,
  nome         VARCHAR(150) NOT NULL,
  genero_id    INT REFERENCES genero(id),
  pais         VARCHAR(60) NOT NULL DEFAULT 'Brasil',
  seguidores   INT DEFAULT 0
);

