CREATE TABLE album (
  id               SERIAL PRIMARY KEY,
  titulo           VARCHAR(200) NOT NULL,
  artista_id       INT REFERENCES artista(id),
  data_lancamento  DATE NOT NULL,
  num_faixas       INT NOT NULL DEFAULT 10
);

