CREATE TABLE reproducao (
  id           SERIAL PRIMARY KEY,
  usuario_id   INT REFERENCES usuario(id),
  musica_id    INT REFERENCES musica(id),
  data_hora    TIMESTAMP NOT NULL,
  duracao_seg  INT NOT NULL,
  dispositivo  VARCHAR(30) NOT NULL CHECK (dispositivo IN ('mobile','desktop','smart_tv','tablet')),
  origem       VARCHAR(30) NOT NULL CHECK (origem IN ('busca','playlist','radio','recomendacao','album'))
);

