-- ============================================================
-- VIEWS ANALÍTICAS — Use para as queries do projeto
-- ============================================================

CREATE OR REPLACE VIEW vw_mrr_mensal AS
SELECT
    DATE_TRUNC('month', data_inicio) AS mes,
    SUM(valor_pago) AS mrr,
    COUNT(*)        AS novas_assinaturas
FROM assinatura
WHERE status = 'ativa' OR (status = 'cancelada' AND data_fim IS NOT NULL)
GROUP BY 1 ORDER BY 1;

CREATE OR REPLACE VIEW vw_top_artistas AS
SELECT
    a.nome AS artista,
    g.nome AS genero,
    COUNT(r.id) AS total_reproducoes,
    COUNT(DISTINCT r.usuario_id) AS usuarios_unicos,
    ROUND(SUM(r.duracao_seg)/3600.0, 1) AS horas_totais
FROM reproducao r
JOIN musica m ON m.id = r.musica_id
JOIN artista a ON a.id = m.artista_id
JOIN genero g ON g.id = m.genero_id
GROUP BY 1,2 ORDER BY 3 DESC;

CREATE OR REPLACE VIEW vw_usuarios_plano_cidade AS
SELECT
    c.nome AS cidade,
    c.estado,
    c.regiao,
    p.nome AS plano,
    COUNT(u.id) AS total_usuarios,
    ROUND(100.0 * COUNT(u.id) / SUM(COUNT(u.id)) OVER (PARTITION BY c.id), 1) AS pct_plano
FROM usuario u
JOIN plano p ON p.id = u.plano_id
JOIN cidade c ON c.id = u.cidade_id
WHERE u.ativo = TRUE
GROUP BY 1,2,3,4 ORDER BY 5 DESC;

