    MAX(r.data_hora::DATE) AS ultima_escuta
FROM usuario u
JOIN reproducao r ON r.usuario_id = u.id
JOIN plano p ON p.id = u.plano_id
JOIN cidade c ON c.id = u.cidade_id
WHERE p.nome = 'gratuito' AND u.ativo = TRUE
GROUP BY u.id, u.nome, c.nome, p.nome
HAVING COUNT(r.id) > 20
ORDER BY horas_ouvidas DESC
LIMIT 20;
*/

